def sample_records(today: date | None = None) -> list[tuple[dict, dict]]:
    """Return (search hit, fetchOpportunity detail) pairs in Grants.gov's shape."""
    today = today or date.today()
    out = []
    for (oid, title, agency, code, alns, prog, desc, status, close_in, ceiling, est, n, elig, instr, cat, cost, cats) in SPECS:
        close = (today + timedelta(days=close_in)).strftime("%m/%d/%Y") if close_in is not None else ""
        opened = (today - timedelta(days=20)).strftime("%m/%d/%Y")
        hit = {"id": str(oid), "number": f"SAMPLE-{oid}", "title": title, "agencyCode": code, "agencyName": agency,
               "openDate": opened, "closeDate": close, "oppStatus": status, "alnist": alns}
        body = {
            "agencyName": agency, "synopsisDesc": f"<p>{desc}</p>", "forecastDesc": f"<p>{desc}</p>",
            "responseDate": close, "estApplicationResponseDate": close,
            "awardCeiling": str(ceiling) if ceiling else "", "estimatedFunding": str(est) if est else "",
            "numberOfAwards": str(n) if n else "", "expectedNumberOfAwards": str(n) if n else "",
            "costSharing": None if cost is None else bool(cost),
            "applicantTypes": [{"id": c} for c in elig],
            "fundingInstruments": [{"id": instr}],
            "fundingActivityCategories": [{"description": c} for c in cats],
            "applicantEligibilityDesc": "",
        }
        detail = {"id": oid, "opportunityNumber": f"SAMPLE-{oid}", "opportunityTitle": title,
                  "opportunityCategory": {"category": cat},
                  "cfdas": [{"cfdaNumber": a, "programTitle": prog} for a in alns],
                  ("forecast" if status == "forecasted" else "synopsis"): body}
        out.append((hit, detail))
    return out
